def default_categories(apps, schema_editor):
    """Companies set up before expenses existed get the same starting categories."""
    from apps.accounting.setup import EXPENSE_CATEGORIES

    Account = apps.get_model("accounting", "Account")
    Category = apps.get_model("accounting", "ExpenseCategory")
    for account in Account.objects.filter(
        code__in=[row[3] for row in EXPENSE_CATEGORIES], is_group=False
    ):
        for code, name, name_ar, account_code in EXPENSE_CATEGORIES:
            if account_code == account.code:
                Category.objects.get_or_create(
                    company_id=account.company_id,
                    code=code,
                    defaults={"name": name, "name_ar": name_ar, "account": account},
                )


